changeSet.sql:
DO $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conname = 'uk_dash_name_sys_owner'
          AND conrelid = 'public.hive_dashboard'::regclass
    ) THEN
        ALTER TABLE public.hive_dashboard DROP CONSTRAINT uk_dash_name_sys_owner;
    END IF;

    IF EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conname = 'hive_dashboard_name_key'
          AND conrelid = 'public.hive_dashboard'::regclass
    ) THEN
        ALTER TABLE public.hive_dashboard DROP CONSTRAINT hive_dashboard_name_key;
    END IF;

    IF EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conname = 'uk_hive_dashboard_name'
          AND conrelid = 'public.hive_dashboard'::regclass
    ) THEN
        ALTER TABLE public.hive_dashboard DROP CONSTRAINT uk_hive_dashboard_name;
    END IF;
END $$;

CREATE UNIQUE INDEX IF NOT EXISTS uk_hive_dashboard_tenant_name
    ON public.hive_dashboard (tenant_id, name)
    WHERE tenant_id IS NOT NULL;

CREATE UNIQUE INDEX IF NOT EXISTS uk_hive_dashboard_global_name
    ON public.hive_dashboard (name)
    WHERE tenant_id IS NULL;
